    /** The `IDiesisPatronCampaignVoucherV1` tuple. */
    data class IDiesisPatronCampaignVoucherV1(
        val campaignId: Bytes32,
        val beneficiary: String,
        val target: String,
        val selector: Bytes4,
        val maxTransactions: BigInteger,
        val maxLifetimeSpend: BigInteger,
        val expiry: BigInteger,
        val nonce: BigInteger,
    ) : StaticStruct(campaignId, Address(beneficiary), Address(target), selector, Uint32(maxTransactions), Uint256(maxLifetimeSpend), Uint64(expiry), Uint256(nonce)) {
        constructor(campaignId: Bytes32, beneficiary: Address, target: Address, selector: Bytes4, maxTransactions: Uint32, maxLifetimeSpend: Uint256, expiry: Uint64, nonce: Uint256) : this(campaignId, beneficiary.value, target.value, selector, maxTransactions.value, maxLifetimeSpend.value, expiry.value, nonce.value)
    }

    /** The `IDiesisPatronGrantInfo` tuple. */
    data class IDiesisPatronGrantInfo(
        val balance: BigInteger,
        val totalContributed: BigInteger,
        val totalSpent: BigInteger,
    ) : StaticStruct(Uint256(balance), Uint256(totalContributed), Uint256(totalSpent)) {
        constructor(balance: Uint256, totalContributed: Uint256, totalSpent: Uint256) : this(balance.value, totalContributed.value, totalSpent.value)
    }

